-- ============================================================
-- Migration compta legacy -> ledger moderne (GENERE, NE PAS EDITER A LA MAIN)
-- Genere par scripts/migration/gen_compta_sql.py
-- Devises : sous-requete sur currency par SYMBOLE (FC=CDF, $=USD), non ambigu.

-- Tables de correspondance : CREATE hors transaction (DDL = commit implicite MySQL).
CREATE TABLE IF NOT EXISTS legacy_subaccount_map (legacy_id INT PRIMARY KEY, new_id BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS legacy_account_map (legacy_id INT PRIMARY KEY, new_id BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- ONE-SHOT TRANSACTIONNEL AUTO-VERIFIE (dev ET prod, via : mysql < fichier)
-- Tout-ou-rien : si un controle echoue (compte/equilibre), SIGNAL -> ROLLBACK.
-- COMMIT seulement si tous les controles passent. Rejouable (idempotent).
-- ============================================================
DROP PROCEDURE IF EXISTS _legacy_migrate;
DELIMITER //
CREATE PROCEDURE _legacy_migrate()
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
-- === account : fusion sur l'existant dev (1-6) + insert Locatif ===
-- account legacy 7 (Locatif) : insere si absent (match par nom+type)

-- === subAccount (84 actifs + 1 inactif(s) requis par un type) : reinseres en id AUTO + map ===
-- accountId recable via legacy_account_map. Idempotent via legacy_subaccount_map.
-- Pour recabler sans LAST_INSERT_ID : on encode le legacy_id dans un marqueur de
-- description temporaire... non dispo ici -> on insere puis on mappe par (name,accountId)
-- du subAccount le PLUS RECENT non encore mappe. 2 statements autonomes + idempotents.

-- === transaction_types (79 actifs) : id AUTO, debit/credit via map subAccount ===

-- === journal_entries + journal_entry_lines (1089 transactions actives) ===
-- 1 tx = 1 entry + 2 lines (deja equilibree). account_id = NEW subAccount id (via map).
-- side en MAJUSCULES (convention code). Idempotent via idempotency_key.
-- Statements autonomes : la ligne retrouve son entry par idempotency_key (pas de @var).

  -- === CONTROLES (SIGNAL -> ROLLBACK si un seul echoue) ===
  IF NOT ((SELECT COUNT(*) FROM journal_entries WHERE source_module='legacy_migration') >= 1089) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Nombre d''ecritures migrees < 1089 attendu -> ROLLBACK';
  END IF;
  IF NOT ((SELECT COALESCE(SUM(amount),0) FROM journal_entry_lines l JOIN journal_entries je ON je.id=l.entry_id WHERE je.source_module='legacy_migration' AND l.side='DEBIT') = (SELECT COALESCE(SUM(amount),0) FROM journal_entry_lines l JOIN journal_entries je ON je.id=l.entry_id WHERE je.source_module='legacy_migration' AND l.side='CREDIT')) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Desequilibre debit != credit -> ROLLBACK';
  END IF;
  IF NOT ((SELECT COUNT(*) FROM journal_entry_lines l JOIN journal_entries je ON je.id=l.entry_id WHERE je.source_module='legacy_migration' AND l.account_id IS NULL) = 0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Lignes sans compte (account_id NULL) -> ROLLBACK';
  END IF;
  COMMIT;
END //
DELIMITER ;
CALL _legacy_migrate();
DROP PROCEDURE _legacy_migrate;
